function UnPACTResultsMethod({ row, column, rowIndex, columnIndex }: any) {
  // 对于非首个单元格，比较左侧单元格的内容
  if (columnIndex > 0) {
    const prevKey = UnPACTResultsDatacolumnsKeys[columnIndex - 1];
    if (row[prevKey] === row[column.property]) {
      return { rowspan: 1, colspan: 0 };
    }
  }
  
  let mergeCount = 1;
  for (let i = columnIndex + 1; i < UnPACTResultsDatacolumnsKeys.length; i++) {
    if (row[UnPACTResultsDatacolumnsKeys[i]] === row[column.property]) {
      mergeCount+=2;
    } else {
      break;
    }
  }
  return { rowspan: 1, colspan: mergeCount };
}



