  if (columnIndex > 0) {
    const prevKey = RecoverResultsDatacolumnsKeys[columnIndex - 1];
    if (row[prevKey] === row[column.property]) {
      return { rowspan: 1, colspan: 0 };
    }
  }
  
  let mergeCount = 1;
  for (let i = columnIndex + 1; i < RecoverResultsDatacolumnsKeys.length; i++) {
    if (row[RecoverResultsDatacolumnsKeys[i]] === row[column.property]) {
