const objectSpanMethod = ({ row, column, rowIndex, columnIndex }) => {
  // 定义需要合并的列及其属性名
  const mergeConfig = {
    1: 'name',   // 第二列合并姓名
    2: 'category' // 第三列合并类别
  };
  
  const prop = mergeConfig[columnIndex];
  if (prop) {
    // 查找当前行之前有多少相同值的行
    let prevRows = 0;
    for (let i = 0; i < rowIndex; i++) {
      if (this.tableData[i][prop] === row[prop]) {
        prevRows++;
      }
    }
    
    // 如果是第一个相同值的行，计算需要合并多少行
    if (prevRows === 0) {
      let rowspan = 1;
      for (let i = rowIndex + 1; i < this.tableData.length; i++) {
        if (this.tableData[i][prop] === row[prop]) {
          rowspan++;
        } else {
          break;
        }
      }
      return { rowspan, colspan: 1 };
    }
    return { rowspan: 0, colspan: 0 }; // 被合并的行
  }
}


